import type { Card, Claim } from '../cards/card.js';
import type { ClaimStatus } from '../cards/card-vocabulary.js';
import { mermaidLabel } from './mermaid-label.js';

// RF-260, RF-508, DEC-134: the Mermaid sequence diagram of a FLOW card, generated by code from its
// steps; the model never writes Mermaid. The trigger is the first participant; each card a step
// touches is a participant, labelled with that card's title (or the id the step names when the
// card is not among the given cards). Each step is a numbered message from where the flow is to
// the card it touches, or to itself when it touches none; each branch is a numbered note; the
// outcome is a note at the end. A rejected step stays and is marked (ADR-005). Participant ids
// are generated (`p1`, `p2`, ...), never taken from the code; every label goes through
// `mermaidLabel`.

const marks: Partial<Record<ClaimStatus, string>> = {
  Rejected: ' (rejected)',
  CitationInvalid: ' (citation invalid)',
};

interface Participants {
  readonly lines: string[];
  readonly idOf: Map<string, string>;
}

function participant(participants: Participants, key: string, label: string): string {
  const known = participants.idOf.get(key);
  if (known !== undefined) return known;
  const id = `p${String(participants.idOf.size + 1)}`;
  participants.idOf.set(key, id);
  participants.lines.push(`  participant ${id} as ${mermaidLabel(label)}`);
  return id;
}

function stepLines(step: Claim, number: number, from: string, to: string): readonly string[] {
  const text = `${String(number)}. ${step.text}${marks[step.status] ?? ''}`;
  const branches = (step.branches ?? []).map((branch) => {
    const label = mermaidLabel(`${String(number)}.${String(branch.number)} ${branch.text}`);
    return `  Note right of ${to}: ${label}`;
  });
  return [`  ${from}->>${to}: ${mermaidLabel(text)}`, ...branches];
}

// RF-260
export function flowSequenceDiagram(flow: Card, cards: readonly Card[]): string {
  const titleOf = new Map(cards.map((card) => [card.id, card.title]));
  const participants: Participants = { lines: [], idOf: new Map() };
  const messages: string[] = [];
  // Keys carry a prefix, so no step target can be taken for the trigger.
  let at = participant(participants, 'trigger', flow.flow?.trigger ?? flow.title);
  flow.claims.forEach((step, index) => {
    const target = step.target;
    const to =
      target === undefined
        ? at
        : participant(participants, `card ${target}`, titleOf.get(target) ?? target);
    messages.push(...stepLines(step, index + 1, at, to));
    at = to;
  });
  if (flow.flow !== undefined) {
    messages.push(`  Note over ${at}: ${mermaidLabel(`Outcome: ${flow.flow.outcome}`)}`);
  }
  return ['sequenceDiagram', ...participants.lines, ...messages, ''].join('\n');
}
